// Session state management functions shared across all strategies.
// SessionState is stored in .git/entire-sessions/{session_id}.json

// getSessionStateDir returns the path to the session state directory.
// This is stored in the git common dir so it's shared across all worktrees.
func getSessionStateDir(ctx context.Context) (string, error) {
	commonDir, err := GetGitCommonDir(ctx)
	if err != nil {
		return "", err
	}
	return filepath.Join(commonDir, session.SessionStateDirName), nil
}

// openSessionStateRoot creates the session state directory if needed and returns
// an os.Root scoped to it. Hint/marker files are named from the (already
// validated) session ID; routing their writes through os.Root makes escaping
// the directory impossible at the kernel level even if validation were bypassed.
// Callers must Close the returned root.
//
// The root is derived from the git common dir's shared root with
// Root.OpenRoot, not opened on an assembled path. That is what makes the
// containment transitive: the state directory is proven to be a real directory
// inside .git before anything is named within it, so neither the directory nor
// the files under it can be redirected out of the clone.
func openSessionStateRoot(ctx context.Context) (*os.Root, error) {
	commonRoot, err := gitdir.Open(ctx)
	if err != nil {
		return nil, fmt.Errorf("failed to open git common dir: %w", err)
	}
	if err := osroot.MkdirAllNoSymlink(commonRoot, session.SessionStateDirName, 0o750); err != nil {
		return nil, fmt.Errorf("failed to create session state directory: %w", err)
	}
	root, err := commonRoot.OpenRoot(session.SessionStateDirName)
	if err != nil {
		return nil, fmt.Errorf("failed to open session state directory: %w", err)
	}
	return root, nil
}

// openSessionStateRootForRead returns an os.Root scoped to the session state
// directory without creating it. Returns (nil, nil) when the directory does not
// exist, so read paths can treat a missing directory as "no hint".
func openSessionStateRootForRead(ctx context.Context) (*os.Root, error) {
	commonRoot, err := gitdir.Open(ctx)
	if os.IsNotExist(err) {
		return nil, nil //nolint:nilnil // no common dir = no hint; callers handle nil root
	}
	if err != nil {
		return nil, fmt.Errorf("failed to open git common dir: %w", err)
	}
	root, err := commonRoot.OpenRoot(session.SessionStateDirName)
	if os.IsNotExist(err) {
		return nil, nil //nolint:nilnil // missing dir = no hint; callers handle nil root
	}
	if err != nil {
		return nil, fmt.Errorf("failed to open session state directory: %w", err)
	}
	return root, nil
}

// LoadSessionState loads the session state for the given session ID.
// Returns (nil, nil) when session file doesn't exist or session is stale (not an error condition).
// Stale sessions are automatically deleted by the underlying StateStore.
func LoadSessionState(ctx context.Context, sessionID string) (*SessionState, error) {
	store, err := session.NewStateStore(ctx)
	if err != nil {
		return nil, fmt.Errorf("failed to create state store: %w", err)
	}

	state, err := store.Load(ctx, sessionID)
	if err != nil {
		return nil, fmt.Errorf("failed to load session state: %w", err)
	}
	return state, nil
}

// SaveSessionState saves the session state atomically.
func SaveSessionState(ctx context.Context, state *SessionState) error {
	store, err := session.NewStateStore(ctx)
	if err != nil {
		return fmt.Errorf("failed to create state store: %w", err)
	}

	if err := store.Save(ctx, state); err != nil {
		return fmt.Errorf("failed to save session state: %w", err)
	}
	return nil
}

// ListSessionStates returns all session states from the state directory.
// This is a package-level function that doesn't require a specific strategy instance.
func ListSessionStates(ctx context.Context) ([]*SessionState, error) {
	store, err := session.NewStateStore(ctx)
	if err != nil {
		return nil, fmt.Errorf("failed to create state store: %w", err)
	}

	states, err := store.List(ctx)
	if err != nil {
		return nil, fmt.Errorf("failed to list session states: %w", err)
	}
	return states, nil
}

// FindMostRecentSession returns the session ID of the most recently interacted session
// (by LastInteractionTime) in the current worktree. Returns empty string if no sessions exist.
// Scoping to the current worktree prevents cross-worktree pollution in log routing.

// Package entiredir owns access to the repository's .entire directory.
//
// Every non-test read and write under .entire goes through the single *os.Root
// this package hands out, rather than through an absolute path assembled by the
// caller. Two properties follow from that, and neither survives if a call site
// reverts to os.ReadFile/os.WriteFile on a joined path:
//
//   - Containment. .entire holds paths named from agent-supplied session IDs,
//     tool-use IDs, and tree paths. A root confines every open to the directory
//     at the kernel level, so a crafted name cannot escape it, and a symlink
//     swapped in between resolution and open (TOCTOU) surfaces as an error
//     rather than a redirected write.
//   - One directory handle per worktree. The root is opened once and memoized,
//     so the hot hook paths stop paying an OpenRoot per state file, and every
//     consumer observes the same directory even if .entire is renamed or
//     replaced underneath a long-running process.
//
// Creation is deliberately lazy and split across two entry points. Open creates
// .entire because its callers are about to write; OpenForRead never creates,
// because a command that only looks must leave an untouched repo untouched.
// That distinction is load-bearing for logging in particular: the log file is
// created by the first line actually written, so a command that logs nothing
// (completion, version, help) must not leave an .entire behind.
//
// Reset exists for the paths that delete the directory (entire disable,
// entire clean) and for tests. A cached root that outlives its directory is a
// handle to an unlinked inode: writes through it succeed and land nowhere.
package entiredir

import (
	"context"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
	"github.com/entireio/cli/cmd/entire/cli/osroot"
	"github.com/entireio/cli/cmd/entire/cli/paths"
)

// dirPerm is the mode .entire is created with. It matches the mode the
// directory already had when each consumer created its own subdirectory.
const dirPerm = 0o750

// ReadFile reads an Entire-owned file without following a symlink at the leaf.
func ReadFile(root *os.Root, name string) ([]byte, error) {
	return osroot.ReadFileNoFollow(root, name) //nolint:wrapcheck // preserve os error classification
}

// WriteFile atomically replaces an Entire-owned file. Renaming a newly-created
// temporary file over name replaces a planted leaf symlink rather than opening
// and truncating its target.
func WriteFile(root *os.Root, name string, data []byte, perm os.FileMode) error {
	return jsonutil.WriteFileAtomicIn(root, name, data, perm) //nolint:wrapcheck // caller supplies path context
}

// Open returns the shared *os.Root for the current worktree's .entire
// directory, creating the directory if it does not exist. Use it from write
// paths; read-only callers want OpenForRead.
//
// The returned root is owned by this package and shared with every other
// caller. Do not close it.
func Open(ctx context.Context) (*os.Root, error) {
	worktreeRoot, err := anchor(ctx)
	if err != nil {
		return nil, err
	}
	return OpenAt(worktreeRoot)
}

// OpenForRead is Open without creating .entire. A missing directory is
// reported as fs.ErrNotExist, which callers classify with errors.Is.
func OpenForRead(ctx context.Context) (*os.Root, error) {
	worktreeRoot, err := anchor(ctx)
	if err != nil {
		return nil, err
	}
	return OpenAtForRead(worktreeRoot)
}

// OpenAt is Open for an explicit worktree root, for the callers that already
// resolved one (or that act on a worktree other than the current directory).
func OpenAt(worktreeRoot string) (*os.Root, error) {
	return open(worktreeRoot, true)
}

// OpenAtForRead is OpenForRead for an explicit worktree root.
func OpenAtForRead(worktreeRoot string) (*os.Root, error) {
	return open(worktreeRoot, false)
}

// Opener returns a thunk that calls Open when invoked, for consumers that are
// handed their storage up front but must not touch the disk until they first
// write (see logging.Config.Root).
func Opener(ctx context.Context) func() (*os.Root, error) {
	return func() (*os.Root, error) { return Open(ctx) }
}

// OpenerAt returns a thunk that calls OpenAt when invoked.
func OpenerAt(worktreeRoot string) func() (*os.Root, error) {
	return func() (*os.Root, error) { return OpenAt(worktreeRoot) }
}

// Path returns the absolute path of the current worktree's .entire directory.
// It is for messages and for the few consumers that must hand a path to an
// external process; it is not an invitation to do I/O on the result.
func Path(ctx context.Context) (string, error) {
	worktreeRoot, err := anchor(ctx)
	if err != nil {
		return "", err
	}
	return filepath.Join(worktreeRoot, paths.EntireDir), nil
}

// Reset closes and forgets every cached root. Call it after deleting .entire:
// a root cached across the deletion refers to an unlinked directory, so writes
// through it succeed and land nowhere.
//
// The registry is shared with the other anchors, so this clears them too. That
// is the behaviour teardown wants — a repo whose .entire just went away is not a
// repo whose .git root is worth keeping — and tests get one reset to call.
func Reset() {
	osroot.ResetShared()
}

// Name converts a repo-relative path under .entire (for example
// paths.EntireTmpDir) to a name relative to the .entire root. The repo-relative
// constants stay as they are because git paths, settings display, and gitignore
// entries all need them; this is the one-line bridge to root-relative I/O.
//
// A path outside .entire is an error rather than a silent passthrough: the
// alternative is a name that resolves inside .entire but means something else.
func Name(repoRelPath string) (string, error) {
	cleaned := filepath.ToSlash(filepath.Clean(filepath.FromSlash(repoRelPath)))
	if cleaned == paths.EntireDir {
		return ".", nil
	}
	rest, ok := strings.CutPrefix(cleaned, paths.EntireDir+"/")
	if !ok || rest == "" {
		return "", fmt.Errorf("%q is not under %s", repoRelPath, paths.EntireDir)
	}
	return rest, nil
}

// MustName is Name for package-level constants that are known to be under
// .entire. It panics on a path that is not, which can only be a programming
// error in a literal.
func MustName(repoRelPath string) string {
	name, err := Name(repoRelPath)
	if err != nil {
		panic(err)
	}
	return name
}

// anchor resolves the directory .entire sits in: the git worktree root, falling
// back to the current directory only on git's positive "not a repository"
// verdict.
//
// The fallback is load-bearing — `entire enable` runs in a directory that is not
// a repository yet — and gating it on paths.ErrNotARepository is what keeps it
// narrow. That sentinel means git ran and said there is no repository here.
// Every other failure (git off $PATH, a cancelled context, dubious ownership, a
// permission error, malformed output) means "we could not find out", and
// answering that with the current directory is how the paths.AbsPath fallback
// this replaces used to give an agent working in a subdirectory of a real repo
// its own .entire beside itself. A root is only as trustworthy as the directory
// it is opened on, so a base this function is not sure about is not a base it
// hands back.
//
// Callers that name a worktree themselves use OpenAt and never reach this.
func anchor(ctx context.Context) (string, error) {
	worktreeRoot, err := paths.WorktreeRoot(ctx)
	switch {
	case err == nil:
		return worktreeRoot, nil
	case !errors.Is(err, paths.ErrNotARepository):
		return "", fmt.Errorf("resolve %s location: %w", paths.EntireDir, err)
	}

	cwd, cwdErr := os.Getwd() //nolint:forbidigo // no repository here; see the doc comment
	if cwdErr != nil {
		return "", fmt.Errorf("resolve %s location: %w", paths.EntireDir, cwdErr)
	}
	return cwd, nil
}

// PathTo returns the absolute path of repoRelPath, which must name something
// under .entire. It exists for the consumers that carry an absolute path in
// their own API — settings resolves one per layer and hands it back to callers
// that print it — so those resolve through this package's anchor rather than
// paths.AbsPath, whose relative fallback is the thing anchor exists to avoid.
func PathTo(ctx context.Context, repoRelPath string) (string, error) {
	if _, err := Name(repoRelPath); err != nil {
		return "", err
	}
	worktreeRoot, err := anchor(ctx)
	if err != nil {
		return "", err
	}
	return filepath.Join(worktreeRoot, filepath.FromSlash(repoRelPath)), nil
}

func open(worktreeRoot string, create bool) (*os.Root, error) {
	if worktreeRoot == "" {
		return nil, errors.New("entiredir: worktree root is required")
	}
	abs, err := filepath.Abs(worktreeRoot)
	if err != nil {
		return nil, fmt.Errorf("resolve %s: %w", worktreeRoot, err)
	}
	return openDir(filepath.Join(abs, paths.EntireDir), create)
}

// openDir is the one place a *os.Root over a .entire directory is created. Every
// entry point funnels here so the create/no-create split stays in a single
// branch; osroot.Shared owns the open-at-most-once part.
func openDir(dir string, create bool) (*os.Root, error) {
	parentDir := filepath.Dir(dir)
	name := filepath.Base(dir)
	parent, err := osroot.Shared(parentDir)
	if err != nil {
		return nil, err
	}
	if create {
		if err := osroot.MkdirAllNoSymlink(parent, name, dirPerm); err != nil {
			return nil, fmt.Errorf("create %s: %w", dir, err)
		}
	}
	return osroot.SharedChild(parent, dir, name) //nolint:wrapcheck // preserves missing-path classification
}

// OpenPath returns the shared root for the .entire directory containing p,
// together with p's name within it, creating the directory if needed.
// OpenPathForRead is the same without creation.
//
// These exist for the consumers that already carry an absolute path — settings
// resolves one per layer, and hands it back to callers that print it — so those
// APIs keep their shape while the open itself still goes through the one root.
// A path not under a .entire directory yields ok=false from Split and an error
// here; callers that legitimately handle both (settings also reads clone
// preferences out of .git) branch on that rather than guessing.
func OpenPath(p string) (root *os.Root, name string, err error) {
	return openPath(p, true)
}

// OpenPathForRead is OpenPath without creating .entire.
func OpenPathForRead(p string) (root *os.Root, name string, err error) {
	return openPath(p, false)
}

// Split splits a path that lies under a .entire directory into that directory
// and the name of the path within it. It is lexical: the path is cleaned and the
// innermost ".entire" component wins, which is the directory that actually
// contains the file if a repo is ever checked out inside another repo's .entire.
//
// A relative path is accepted, because paths.AbsPath still falls back to one
// when it cannot resolve a worktree root and callers hand that value straight
// through. The walk is component-by-component with filepath rather than a split
// on separators so a Windows volume name survives being rejoined.
func Split(p string) (entireDir, name string, ok bool) {
	cleaned := filepath.Clean(p)
	rest := cleaned
	for {
		dir, base := filepath.Split(rest)
		if base == "" {
			return "", "", false
		}
		if base == paths.EntireDir {
			rel, relErr := filepath.Rel(rest, cleaned)
			// rel == "." means the caller named the directory itself, which is
			// not a file within it.
			if relErr != nil || rel == "." || paths.IsRelativeTraversal(rel) {
				return "", "", false
			}
			return rest, filepath.ToSlash(rel), true
		}
		if dir == "" {
			return "", "", false // reached the start of a relative path
		}
		parent := filepath.Clean(dir)
		if parent == rest {
			return "", "", false // reached the filesystem root
		}
		rest = parent
	}
}

func openPath(p string, create bool) (*os.Root, string, error) {
	dir, name, ok := Split(p)
	if !ok {
		return nil, "", fmt.Errorf("%q is not under a %s directory", p, paths.EntireDir)
	}
	// A relative path is rejected rather than resolved against the current
	// directory: that is the cwd anchor anchor() refuses, reached by another
	// route. Callers resolve their path from the worktree root before getting
	// here.
	if !filepath.IsAbs(dir) {
		return nil, "", fmt.Errorf("%q is not absolute; resolve it against the worktree root first", p)
	}
	root, err := openDir(dir, create)
	if err != nil {
		return nil, "", err
	}
	return root, name, nil
}

package agent

import (
	"fmt"
	"os"
	"path/filepath"

	"github.com/entireio/cli/cmd/entire/cli/entiredir"
	"github.com/entireio/cli/cmd/entire/cli/osroot"
)

// ReadTranscriptFile reads a transcript path while preserving the .entire
// boundary for agents whose stable transcript cache lives there (OpenCode and
// Pi). Agent-owned transcript stores remain explicit external paths and retain
// their existing behavior.
func ReadTranscriptFile(filePath string) ([]byte, error) {
	if _, _, underEntire := entiredir.Split(filePath); !underEntire {
		return os.ReadFile(filePath) //nolint:gosec // external agent transcript path is the caller's selected input
	}
	abs, err := filepath.Abs(filePath)
	if err != nil {
		return nil, err
	}
	root, name, err := entiredir.OpenPathForRead(abs)
	if err != nil {
		return nil, err
	}
	return entiredir.ReadFile(root, name)
}

// StatTranscriptFile is the metadata-only counterpart to ReadTranscriptFile.
// Lstat is intentional under .entire: a dangling or redirected transcript link
// is not the cached file whose existence the caller is testing.
func StatTranscriptFile(filePath string) (os.FileInfo, error) {
	if _, _, underEntire := entiredir.Split(filePath); !underEntire {
		return os.Stat(filePath) //nolint:gosec // external agent transcript path is the caller's selected input
	}
	abs, err := filepath.Abs(filePath)
	if err != nil {
		return nil, err
	}
	root, name, err := entiredir.OpenPathForRead(abs)
	if err != nil {
		return nil, err
	}
	info, err := root.Lstat(name)
	if err != nil {
		return nil, err //nolint:wrapcheck // preserve missing-file classification
	}
	if info.Mode()&os.ModeSymlink != 0 {
		return nil, fmt.Errorf("%s: %w", name, osroot.ErrSymlinkedPath)
	}
	return info, nil
}
=== SESSION STORE ===
package agent

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"

	"github.com/entireio/cli/cmd/entire/cli/agent/types"
	"github.com/entireio/cli/cmd/entire/cli/osroot"
	"github.com/entireio/cli/cmd/entire/cli/paths"
)

// SessionStore is one agent's own session directory, held as an *os.Root.
//
// Every agent keeps its transcripts somewhere Entire does not own —
// ~/.claude/projects/<hash>/, ~/.codex/sessions/, Cursor's SQLite store,
// ~/.pi/agent/sessions/<encoded-repo>/, a temp dir for OpenCode — and Entire
// reads and writes into all of them. The session ID that selects a file inside
// one comes from an agent hook payload, so this is where an untrusted name
// becomes a path, and a store gives each agent one handle to resolve it through.
//
// It deliberately does NOT try to contain the agent's own writes: the agent is a
// separate process writing its own store. What it contains is Entire's reads and
// writes, which is the half Entire is responsible for.
type SessionStore struct {
	agent SessionLocator
	dir   string
}

// SessionLocator is the slice of Agent a session store needs: where the agent
// keeps sessions for a repo, and how it names a session's file inside that
// directory. Narrow on purpose — a store has no business with transcripts,
// chunking, or hooks, and depending on three methods instead of thirty is what
// lets a test supply one without implementing the whole agent contract.
type SessionLocator interface {
	Name() types.AgentName
	GetSessionDir(repoPath string) (string, error)
	ResolveSessionFile(sessionDir, agentSessionID string) string
}

// ErrOutsideSessionStore reports a session file that does not lie inside the
// agent's session directory. Callers match it with errors.Is.
var ErrOutsideSessionStore = errors.New("path is outside the agent's session directory")

// OpenSessionStore returns ag's session store for repoPath.
//
// The directory need NOT exist yet: resolving a session file is path arithmetic
// plus a containment check, and callers legitimately ask where a transcript
// *would* live before anything has created the directory. Only the I/O methods
// need the directory, and they open the root at that point — memoized per
// directory via osroot.Shared, so every call site in one repo shares a handle.
func OpenSessionStore(ag SessionLocator, repoPath string) (*SessionStore, error) {
	if ag == nil {
		return nil, errors.New("agent is required to open a session store")
	}
	dir, err := ag.GetSessionDir(repoPath)
	if err != nil {
		return nil, fmt.Errorf("resolve %s session directory: %w", ag.Name(), err)
	}
	return OpenSessionStoreAt(ag, dir)
}

// OpenSessionStoreAt is OpenSessionStore for a session directory the caller
// already resolved — the cross-project fallbacks that scan sibling directories,
// and agentimport, which is handed one.
func OpenSessionStoreAt(ag SessionLocator, dir string) (*SessionStore, error) {
	if dir == "" {
		return nil, errors.New("session directory is required")
	}
	abs, err := filepath.Abs(dir)
	if err != nil {
		return nil, fmt.Errorf("resolve %s: %w", dir, err)
	}
	return &SessionStore{agent: ag, dir: abs}, nil
}

// Dir returns the store's absolute directory. It is for messages and for the
// paths Entire hands to other processes (an agent's own resume command, a
// transcript path recorded as a checkpoint's SessionRef); it is not an
// invitation to do I/O on the result.
func (s *SessionStore) Dir() string { return s.dir }

// Root returns the store's shared *os.Root, opening it on first use. Owned by
// the registry: do not close. A directory that does not exist is reported
// unwrapped so callers can classify it with os.IsNotExist.
func (s *SessionStore) Root() (*os.Root, error) {
	return osroot.Shared(s.dir) //nolint:wrapcheck // see doc comment
}

// rootForWrite is Root with the store directory created first. The directory is
// the root itself, so it cannot be created through it — this is the one place
// that reaches it from the outside.
func (s *SessionStore) rootForWrite() (*os.Root, error) {
	if err := os.MkdirAll(s.dir, 0o750); err != nil {
		return nil, fmt.Errorf("create session directory: %w", err)
	}
	return s.Root()
}

// SessionFile resolves agentSessionID to a name inside the store, and to the
// absolute path of the same file.
//
// This is the check the whole type exists for. The agent decides its own file
// layout via ResolveSessionFile — some nest, some append an extension — and the
// ID reaching it came from a hook payload. Converting the result back into a
// name relative to the store rejects an ID that walked out of the directory,
// which a plain filepath.Join would have produced silently.
func (s *SessionStore) SessionFile(agentSessionID string) (name, absPath string, err error) {
	resolved := s.agent.ResolveSessionFile(s.dir, agentSessionID)
	name, err = s.Name(resolved)
	if err != nil {
		return "", "", err
	}
	return name, resolved, nil
}

// Name converts a path into a name inside the store, reporting
// ErrOutsideSessionStore for one that is not. A path already relative to the
// store is accepted as-is.
func (s *SessionStore) Name(p string) (string, error) {
	if p == "" {
		return "", fmt.Errorf("%w: empty path", ErrOutsideSessionStore)
	}
	if !filepath.IsAbs(p) {
		cleaned := filepath.ToSlash(filepath.Clean(filepath.FromSlash(p)))
		if cleaned == "." || paths.IsRelativeTraversal(cleaned) {
			return "", fmt.Errorf("%w: %s", ErrOutsideSessionStore, p)
		}
		return cleaned, nil
	}
	rel, err := filepath.Rel(s.dir, p)
	if err != nil || rel == "." || paths.IsRelativeTraversal(rel) {
		return "", fmt.Errorf("%w: %s is not inside %s", ErrOutsideSessionStore, p, s.dir)
	}
	return filepath.ToSlash(rel), nil
}

// ReadFile reads name from the store.
func (s *SessionStore) ReadFile(name string) ([]byte, error) {
	root, err := s.Root()
	if err != nil {
		return nil, err
	}
	return osroot.ReadFile(root, name) //nolint:wrapcheck // preserved for os.IsNotExist at call sites
}

// WriteFile writes name in the store, creating parent directories. Session
// layouts nest (Gemini keys by project hash, Pi by encoded repo path), so the
// parents are made here rather than at each call site.
func (s *SessionStore) WriteFile(name string, data []byte, perm os.FileMode) error {
	root, err := s.rootForWrite()
	if err != nil {
		return err
	}
	if dir := filepath.ToSlash(filepath.Dir(filepath.FromSlash(name))); dir != "." {
		if err := osroot.MkdirAllNoSymlink(root, dir, 0o750); err != nil {
			return fmt.Errorf("create session directory: %w", err)
		}
	}
	return osroot.WriteFile(root, name, data, perm) //nolint:wrapcheck // preserved for os.IsNotExist at call sites
}

// Exists reports whether name is present in the store. Lstat, not Stat: a
// dangling symlink is still a file that exists and must not be overwritten
// silently (see the rewind restore path, which distinguishes the two).
func (s *SessionStore) Exists(name string) bool {
	root, err := s.Root()
	if err != nil {
		return false
	}
	_, err = root.Lstat(name)
	return err == nil
}

// WriteSessionFile writes data to s.SessionRef through ag's own session store,
// creating parent directories.
//
// It exists because every agent's WriteSession was the same four lines —
// os.MkdirAll of the parent, then os.WriteFile of an absolute SessionRef — eight
// times over, each one taking the path on trust. Routing them through the store
// makes the containment one decision instead of eight, and the parent-directory
// create stops being something each agent has to remember.
//
// The store is anchored on s.RepoPath when it is set, which is the agent's real
// session directory for that repo. When it is not (callers that only carry a
// path, such as a restore driven from checkpoint metadata), the SessionRef's own
// directory anchors it: that contains nothing by itself, but it keeps the write
// on the same code path, and SessionRef there came from Entire's own resolution
// rather than from an agent payload.
func WriteSessionFile(ag SessionLocator, s *AgentSession, data []byte, perm os.FileMode) error {
	if s == nil {
		return errors.New("session is nil")
	}
	if s.SessionRef == "" {
		return errors.New("session reference (transcript path) is required")
	}

	store, err := sessionStoreForWrite(ag, s)
	if err != nil {
		return err
	}
	name, err := store.Name(s.SessionRef)
	if err != nil {
		return fmt.Errorf("write session: %w", err)
	}
	if err := store.WriteFile(name, data, perm); err != nil {
		return fmt.Errorf("failed to write transcript: %w", err)
	}
	return nil
}

// sessionStoreForWrite resolves the store a session write lands in.
//
// With a RepoPath, that is the agent's session directory for it, and a
// SessionRef outside that directory is an ERROR rather than a reason to anchor
// somewhere else. It used to fall through to SessionRef's own parent, which made
// the containment check its own off switch: the one input that fails it was the
// one input that disabled it. The comment justifying that said some agents
// resolve a restored session to a sibling directory — they do not.
// RestoredSessionPathResolver's only implementation (Codex) returns
// <sessionDir>/YYYY/MM/DD/rollout-*.jsonl, which nests INSIDE the store, so the
// branch was unreachable as well as unsound.
//
// Without a RepoPath the SessionRef's own directory is the only candidate there
// is. That anchor contains nothing by itself, and it is kept because the
// alternative is refusing to write at all; what makes it acceptable is that
// SessionRef there came from Entire's own resolution rather than from an agent
// payload.
func sessionStoreForWrite(ag SessionLocator, s *AgentSession) (*SessionStore, error) {
	if s.RepoPath == "" {
		return OpenSessionStoreAt(ag, filepath.Dir(s.SessionRef))
	}

	store, err := OpenSessionStore(ag, s.RepoPath)
	if err != nil {
		return nil, err
	}
	if _, nameErr := store.Name(s.SessionRef); nameErr != nil {
		return nil, fmt.Errorf("%w: %s is not inside %s's session directory %s",
			ErrOutsideSessionStore, s.SessionRef, ag.Name(), store.Dir())
	}
	return store, nil
}

