// open creates the log file. Caller holds mu. A failure is remembered so the
// next line does not retry the syscalls.
func (l *Logger) open() error {
	if l.openErr != nil {
		return l.openErr
	}
	root, err := l.root()
	if err != nil {
		l.openErr = fmt.Errorf("open log root: %w", err)
		return l.openErr
	}
	// NoSymlink: a symlinked log directory is a directory Entire did not create
	// and cannot vouch for, and doctor reports it by name. Failing here is what
	// makes EnsureOpen able to say so.
	if err := osroot.MkdirAllNoSymlink(root, l.dir, 0o750); err != nil {
		l.openErr = fmt.Errorf("create log directory: %w", err)
		return l.openErr
	}
	f, err := osroot.OpenFileNoFollow(root, l.dir+"/"+LogFileName, os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0o600)
	if err != nil {
		l.openErr = fmt.Errorf("open log file: %w", err)
		return l.openErr
	}
	l.file = f
	l.buf = bufio.NewWriterSize(f, writeBufferSize)
	return nil
}

