package gitrepo_test

import (
	"context"
	"os"
	"path/filepath"
	"testing"

	"github.com/entireio/cli/cmd/entire/cli/gitrepo"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/testutil"
)

func TestZZOpenCurrentFallbackTargetsTheWrongRepo(t *testing.T) {
	base := t.TempDir()
	repoA := filepath.Join(base, "repoA") // the repo the hook is running for
	repoB := filepath.Join(base, "repoB") // an unrelated repo we happen to sit in
	for _, d := range []string{repoA, repoB} {
		if err := os.MkdirAll(d, 0o750); err != nil {
			t.Fatal(err)
		}
		testutil.InitRepo(t, d)
	}
	t.Chdir(repoB)
	// Exactly what git exports to a hook it runs for repoA.
	t.Setenv("GIT_DIR", filepath.Join(repoA, ".git"))
	t.Setenv("GIT_WORK_TREE", repoA)

	paths.ClearWorktreeRootCache()
	root, err := paths.WorktreeRoot(context.Background())
	t.Logf("git present : WorktreeRoot = %q (err=%v)", root, err)

	repo, err := gitrepo.OpenCurrent(context.Background())
	if err == nil {
		st, _ := repo.Storer.(interface{ Root() string })
		t.Logf("git present : OpenCurrent opened a repo ok; storer=%v", st != nil)
	}

	// Now make the git binary unavailable, which is the only way to reach the
	// repoRoot = "." fallback.
	t.Setenv("PATH", t.TempDir())
	paths.ClearWorktreeRootCache()
	root2, err2 := paths.WorktreeRoot(context.Background())
	t.Logf("git absent  : WorktreeRoot = %q (err=%v)", root2, err2)

	repo2, err3 := gitrepo.OpenCurrent(context.Background())
	t.Logf("git absent  : OpenCurrent err=%v", err3)
	if err3 == nil {
		cfg, _ := repo2.Config()
		_ = cfg
		// Prove which repo we actually got by writing a ref and looking on disk.
		t.Logf("git absent  : OpenCurrent SUCCEEDED while GIT_DIR names %s", filepath.Join(repoA, ".git"))
		t.Logf("            : cwd is %s", repoB)
	}
}
EOF
